// 1. Validate Configuration
int config_valid = TRUE32;
if (gb_input.enable != 0 && gb_input.enable != 1) {
    config_valid = FALSE32;
} else if (!isfinite(gb_config.stationary_limit) || gb_config.stationary_limit < 0.0) {
    config_valid = FALSE32;
} else if (gb_config.required < 2 || gb_config.required > 100) {
    config_valid = FALSE32;
}

if (!config_valid) {
    gb_state.mode = GB_FAULT;
    gb_state.count = 0;
    gb_state.rejected = 0;
    gb_state.sum.x = 0.0;
    gb_state.sum.y = 0.0;
    gb_state.sum.z = 0.0;
    gb_state.bias.x = 0.0;
    gb_state.bias.y = 0.0;
    gb_state.bias.z = 0.0;

    gb_output.mode = GB_FAULT;
    gb_output.count = 0;
    gb_output.rejected = 0;
    gb_output.bias = gb_state.bias;
    gb_output.sum_energy = 0.0;
    return;
}

// 2. Handle Enable == 0
if (gb_input.enable == 0) {
    gb_state.mode = GB_IDLE;
    gb_state.count = 0;
    gb_state.rejected = 0;
    gb_state.sum.x = 0.0;
    gb_state.sum.y = 0.0;
    gb_state.sum.z = 0.0;
    gb_state.bias.x = 0.0;
    gb_state.bias.y = 0.0;
    gb_state.bias.z = 0.0;

    gb_output.mode = GB_IDLE;
    gb_output.count = 0;
    gb_output.rejected = 0;
    gb_output.bias = gb_state.bias;
    gb_output.sum_energy = 0.0;
    return;
}

// 3. Sample Validity Check
if (gb_input.sample == NULL || !adcs_is_finite_vec3(gb_input.sample)) {
    gb_state.mode = GB_FAULT;
    gb_state.count = 0;
    gb_state.rejected = 0;
    gb_state.sum.x = 0.0;
    gb_state.sum.y = 0.0;
    gb_state.sum.z = 0.0;
    gb_state.bias.x = 0.0;
    gb_state.bias.y = 0.0;
    gb_state.bias.z = 0.0;

    gb_output.mode = GB_FAULT;
    gb_output.count = 0;
    gb_output.rejected = 0;
    gb_output.bias = gb_state.bias;
    gb_output.sum_energy = 0.0;
    return;
