        gb_state.rejected++;
        gb_state.count = 0;
        gb_state.sum.x = 0.0;
        gb_state.sum.y = 0.0;
        gb_state.sum.z = 0.0;
        gb_state.bias.x = 0.0;
        gb_state.bias.y = 0.0;
        gb_state.bias.z = 0.0;

        gb_output.mode = GB_COLLECT;
