    else {
        // Stationary sample: Accumulate
        gb_state.sum = adcs_vec3_add(&gb_state.sum, gb_input.sample);
        gb_state.count++;

        if (gb_state.count < gb_config.required) {
            // Continue collecting
            gb_state.bias.x = 0.0;
            gb_state.bias.y = 0.0;
            gb_state.bias.z = 0.0;

            gb_output.mode = GB_COLLECT;
            gb_output.count = gb_state.count;
            gb_output.rejected = gb_state.rejected;
            gb_output.bias = gb_state.bias;
            gb_output.sum_energy = 0.0;
        } 
        else {
            // Reached required samples: Publish and Freeze
            gb_state.bias = adcs_vec3_scale(&gb_state.sum, 1.0 / gb_state.count);
            gb_state.mode = GB_READY; // Update internal state to READY

            gb_output.mode = GB_READY;
